import{c as o,Q as e,j as r,m as t}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"Formal Methods in Robot Policy Learning and Verification: A Survey on Current Techniques and Future Directions","description":"","frontmatter":{"url":"https://arxiv.org/abs/2602.06971","title":"Formal Methods in Robot Policy Learning and Verification: A Survey on Current Techniques and Future Directions","archived_date":"2026-06-28","arxiv_id":"2602.06971","authors":["Anastasios Manganaris","Vittorio Giammarino","Ahmed H. Qureshi","Suresh Jagannathan"],"domain":"formal-verification-robotics","pdf_path":"pdfs/2602.06971.pdf","published_date":"2026-01-09","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-01-09-formal-methods-robot-policy-2602-06971.md","filePath":"research/papers/2026-01-09-formal-methods-robot-policy-2602-06971.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-01-09-formal-methods-robot-policy-2602-06971.md"};function n(s,a,l,c,d,p){return e(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="formal-methods-in-robot-policy-learning-and-verification" tabindex="-1">Formal Methods in Robot Policy Learning and Verification <a class="header-anchor" href="#formal-methods-in-robot-policy-learning-and-verification" aria-label="Permalink to &quot;Formal Methods in Robot Policy Learning and Verification&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>隨著機器人系統透過深度學習大幅提升性能，形式方法（formal methods）已成為指定可接受行為、驗證策略正確性的關鍵工具。本綜述論文發表於 TMLR（Transactions on Machine Learning Research），系統梳理該領域現狀。</p><p>**核心張力：**深度神經網路策略雖使機器人性能大幅提升，卻呈現傳統形式分析的挑戰——「僵硬、脆弱、難以詮釋」。這正是形式驗證在機器人策略的核心開放問題。</p><p><strong>兩大支柱：</strong></p><ol><li><strong>策略學習的形式方法</strong>：如何將規格說明（specification）整合進 RL/模仿學習，使學習本身滿足形式正確性</li><li><strong>策略驗證</strong>：針對已訓練的神經網路策略，如何機械地驗證其在所有可能輸入下的行為邊界</li></ol><p><strong>可擴展性是核心瓶頸</strong>：採樣式（sampling-based）、動態規劃式（DP-based）、神經網路近似式（NN-approximation-based）三類方法各有 scalability/expressiveness 取捨。論文識別出形式驗證仍無法在實際規模機器人系統上適用的根本障礙。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>formal/verification 關鍵詞在既有題庫命中 <strong>0 次</strong>（排除無關的 &quot;lets-verify-step-by-step&quot; 論文後）。Workspace 現有版圖集中於 LLM/agent 軟體層，無任何機器人策略形式驗證或安全可信賴性保證的覆蓋。</p>',9)])])}const f=o(i,[["render",n]]);export{m as __pageData,f as default};
